const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const r = spawnSync("node", ["/w/node_modules/wrangler/bin/wrangler.js", "--help"], { encoding: "utf8", env: { ...process.env, WRANGLER_SEND_METRICS: "false", CI: "1" }, timeout: 60000 });
const out = (r.stdout || "") + (r.stderr || "");
const line = out.split("\n").find((l) => l.includes("wrangler preview"));
if (!line) broken("no wrangler preview line in help output: " + out.slice(0, 300));
if (!line.includes("open beta")) symptom("wrangler preview is not labeled open beta in help output");
console.log("OK: " + line.trim());

